/* ============================================
   DAY TIMELINE
   A label column and a track of hours. Bars sit
   on the track by their start and length as a
   share of the day shown, on logical insets, so
   the day runs from the reading direction's
   start. A bar wears the calendar's event pill:
   the event fill with an accent edge and the
   label in the primary text colour, so it reads
   on every theme whatever the accent.
   ============================================ */

/* Base */
.ds-day-timeline {
  --ds-day-timeline-label: 9rem;

  min-width: 0;
}

/* A narrow column scrolls the day sideways; ScrollRegion makes it a
   keyboard stop only while it does. */
.ds-day-timeline__scroll {
  display: flex;
  flex-direction: column;
  overflow-x: auto;
}

/* Header: the label column's title and the hour ticks */
.ds-day-timeline__head {
  display: grid;
  grid-template-columns: var(--ds-day-timeline-label) minmax(0, 1fr);
  min-width: calc(var(--ds-day-timeline-label) + var(--ds-day-timeline-hours, 16) * var(--gap-1000));
  padding-block-end: var(--padding-200);
  border-block-end: var(--border-025) solid var(--color-divider);
}

.ds-day-timeline__row-header,
.ds-day-timeline__tick {
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  letter-spacing: var(--font-caption-letter-spacing);
  color: var(--color-text-tertiary);
}

.ds-day-timeline__axis {
  position: relative;
  min-height: var(--font-caption-line-height);
}

.ds-day-timeline__tick {
  position: absolute;
  inset-block-start: 0;
  transform: translateX(calc(-50% * var(--ds-inline-sign, 1)));
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* The ticks centre on their hour; the first and last sit inside the axis
   so neither hangs past the track's ends. */
.ds-day-timeline__tick:first-child {
  transform: none;
}

.ds-day-timeline__tick:last-child {
  transform: translateX(calc(-100% * var(--ds-inline-sign, 1)));
}

/* Rows */
.ds-day-timeline__rows {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  min-width: calc(var(--ds-day-timeline-label) + var(--ds-day-timeline-hours, 16) * var(--gap-1000));
}

.ds-day-timeline__row {
  display: grid;
  grid-template-columns: var(--ds-day-timeline-label) minmax(0, 1fr);
  align-items: center;
  min-height: var(--control-height-default);
  border-block-end: var(--border-025) solid var(--color-divider);
}

.ds-day-timeline__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding-inline-end: var(--padding-300);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-primary);
}

.ds-day-timeline__track {
  position: relative;
  align-self: stretch;
}

/* Each hour's line sits on the hour, its width back over it, so the last
   one stays inside the track's end. */
.ds-day-timeline__gridline {
  position: absolute;
  inset-block: 0;
  margin-inline-start: calc(var(--border-025) * -1);
  border-inline-start: var(--border-025) solid var(--color-divider);
}

/* The time now: a line across the row in the error role, the convention
   for a live marker on a schedule. */
.ds-day-timeline__now {
  position: absolute;
  inset-block: 0;
  border-inline-start: var(--border-050) solid var(--color-status-error-border);
}

/* Bars */
.ds-day-timeline__bar {
  --ds-day-timeline-accent: var(--color-status-neutral-border);

  position: absolute;
  inset-block: var(--padding-100);
  display: flex;
  align-items: center;
  min-width: 0;
  margin: 0;
  padding: 0 var(--padding-150);
  overflow: hidden;
  background-color: var(--color-calendar-event-bg);
  border: var(--border-025) solid var(--color-calendar-event-border);
  border-inline-start: var(--border-050) solid var(--ds-day-timeline-accent);
  border-radius: var(--radius-100);
  text-align: start;
}

button.ds-day-timeline__bar {
  cursor: pointer;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

button.ds-day-timeline__bar:hover {
  background-color: var(--color-calendar-event-bg-hover);
}

button.ds-day-timeline__bar:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-day-timeline__bar-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

/* Accents: the core accent roles, never the action colour */
.ds-day-timeline__bar--coral {
  --ds-day-timeline-accent: var(--color-core-accent-coral);
}

.ds-day-timeline__bar--violet {
  --ds-day-timeline-accent: var(--color-core-accent-violet);
}

.ds-day-timeline__bar--cobalt {
  --ds-day-timeline-accent: var(--color-core-accent-cobalt);
}

.ds-day-timeline__bar--amber {
  --ds-day-timeline-accent: var(--color-core-accent-amber);
}

.ds-day-timeline__bar--gold {
  --ds-day-timeline-accent: var(--color-core-accent-gold);
}

.ds-day-timeline__bar--mint {
  --ds-day-timeline-accent: var(--color-core-accent-mint);
}

import React from "react";
import { DEFAULT_LOCALE } from "../../behaviors/locale";
import { ScrollRegion } from "../../behaviors/ScrollRegion";
import "../../behaviors/visually-hidden.css";
import "../../behaviors/direction.css";
import "./DayTimeline.css";

/** The accents a bar can take, the core accent roles the calendar's events use. */
export type DayTimelineColor =
  "neutral" | "coral" | "violet" | "cobalt" | "amber" | "gold" | "mint";

/** One stretch of time on a row: a shift, a booking, a meeting. */
export interface DayTimelineBar {
  /** A stable id for the bar. */
  id: string;
  /** When it starts, as 24-hour `HH:MM`. */
  start: string;
  /** When it ends, as 24-hour `HH:MM`. */
  end: string;
  /** A short label on the bar ("Front desk", "Break"). */
  label?: string;
  /** The bar's accent. Defaults to `neutral`. */
  color?: DayTimelineColor;
}

/** One row of the timeline: a person, a room, a machine. */
export interface DayTimelineRow {
  /** A stable id for the row. */
  id: string;
  /** What the row is, shown in the label column. */
  label: string;
  /** The row's bars, in any order. */
  bars: DayTimelineBar[];
}

/** Props owned by DayTimeline itself; everything else falls through to the root `<div>`. */
type DayTimelineOwnProps = {
  /** The rows, top to bottom. */
  rows: DayTimelineRow[];
  /** The first hour the axis shows, 0 to 23. Defaults to 6. */
  startHour?: number;
  /** The hour the axis ends at, 1 to 24. Defaults to 22. */
  endHour?: number;
  /** A line at this time (`HH:MM`), such as the time now. */
  now?: string;
  /** The timeline's name, read before its rows ("Shifts, Tuesday 4 March"). */
  label: string;
  /** The header of the label column. Defaults to "Name". */
  rowHeader?: string;
  /** Called with the bar and its row when a bar is pressed; bars are buttons only when it is set. */
  onBarClick?: (bar: DayTimelineBar, row: DayTimelineRow) => void;
  /** The BCP 47 locale the times are written in, such as `de-DE`. Defaults to `en-US`. This component can render from a Server Component, so it takes the prop alone and reads no LocaleProvider. */
  locale?: string;
  /** Additional CSS classes */
  className?: string;
};

export interface DayTimelineProps
  extends
    DayTimelineOwnProps,
    Omit<
      React.ComponentPropsWithRef<"div">,
      keyof DayTimelineOwnProps | "children"
    > {}

/** Minutes since midnight for `HH:MM`, or null when it is not a time. */
const minutesOf = (time: string): number | null => {
  const match = /^(\d{1,2}):(\d{2})$/.exec(time);
  if (!match) return null;
  return Number(match[1]) * 60 + Number(match[2]);
};

/**
 * Hours within one day: a row per person or resource, a bar from each
 * start to its end, on an axis of hours in the reader's locale. Shifts, room
 * bookings, a machine's runs. Each bar is named with its row and its times,
 * and its label sits on the calendar's event fill, so it reads in every
 * theme whatever the accent. Server-renderable.
 */
export function DayTimeline({
  rows,
  startHour = 6,
  endHour = 22,
  now,
  label,
  rowHeader = "Name",
  onBarClick,
  locale = DEFAULT_LOCALE,
  className = "",
  style,
  ref,
  ...rest
}: DayTimelineProps) {
  const from = Math.max(0, Math.min(23, startHour)) * 60;
  const to = Math.max(from / 60 + 1, Math.min(24, endHour)) * 60;
  const span = to - from;
  const at = (minutes: number) =>
    ((Math.min(Math.max(minutes, from), to) - from) / span) * 100;

  const hourFormat = new Intl.DateTimeFormat(locale, { hour: "numeric" });
  const timeFormat = new Intl.DateTimeFormat(locale, {
    hour: "numeric",
    minute: "2-digit",
  });
  const asDate = (minutes: number) =>
    new Date(2000, 0, 1, Math.floor(minutes / 60), minutes % 60);
  const range = (start: number, end: number) =>
    timeFormat.formatRange(asDate(start), asDate(end));

  const hours: number[] = [];
  for (let h = from / 60; h <= to / 60; h++) hours.push(h);
  const nowMinutes = now ? minutesOf(now) : null;

  const classes = ["ds-day-timeline", className].filter(Boolean).join(" ");
  return (
    <div
      role="group"
      aria-label={label}
      {...rest}
      ref={ref}
      className={classes}
      style={
        {
          ...style,
          "--ds-day-timeline-hours": hours.length - 1,
        } as React.CSSProperties
      }
    >
      <ScrollRegion className="ds-day-timeline__scroll">
        <div className="ds-day-timeline__head" aria-hidden="true">
          <span className="ds-day-timeline__row-header">{rowHeader}</span>
          <div className="ds-day-timeline__axis">
            {hours.map((h) => (
              <span
                key={h}
                className="ds-day-timeline__tick"
                style={{ insetInlineStart: `${at(h * 60)}%` }}
              >
                {h < 24 ? hourFormat.format(asDate(h * 60)) : ""}
              </span>
            ))}
          </div>
        </div>
        <ul className="ds-day-timeline__rows">
          {rows.map((row) => (
            <li key={row.id} className="ds-day-timeline__row">
              <span className="ds-day-timeline__label">{row.label}</span>
              <div className="ds-day-timeline__track">
                {hours.map((h) => (
                  <span
                    key={h}
                    className="ds-day-timeline__gridline"
                    style={{ insetInlineStart: `${at(h * 60)}%` }}
                    aria-hidden="true"
                  />
                ))}
                {nowMinutes !== null &&
                  nowMinutes >= from &&
                  nowMinutes <= to && (
                    <span
                      className="ds-day-timeline__now"
                      style={{ insetInlineStart: `${at(nowMinutes)}%` }}
                      aria-hidden="true"
                    />
                  )}
                {row.bars.map((bar) => {
                  const start = minutesOf(bar.start);
                  const end = minutesOf(bar.end);
                  if (start === null || end === null || end <= start)
                    return null;
                  const name = `${row.label}, ${bar.label ? `${bar.label}, ` : ""}${range(start, end)}`;
                  const barClass = `ds-day-timeline__bar ds-day-timeline__bar--${bar.color ?? "neutral"}`;
                  const barStyle = {
                    insetInlineStart: `${at(start)}%`,
                    inlineSize: `${at(end) - at(start)}%`,
                  };
                  const content = (
                    <>
                      <span
                        className="ds-day-timeline__bar-label"
                        aria-hidden="true"
                      >
                        {bar.label ?? range(start, end)}
                      </span>
                      <span className="ds-visually-hidden">{name}</span>
                    </>
                  );
                  return onBarClick ? (
                    <button
                      key={bar.id}
                      type="button"
                      className={barClass}
                      style={barStyle}
                      onClick={() => onBarClick(bar, row)}
                    >
                      {content}
                    </button>
                  ) : (
                    <span key={bar.id} className={barClass} style={barStyle}>
                      {content}
                    </span>
                  );
                })}
              </div>
            </li>
          ))}
        </ul>
      </ScrollRegion>
    </div>
  );
}
